@spec view_context_spec  src=tests/specs/view_context_spec.lua  loc=589  sha=9c29f58  cases=35
@exercises tuning (tuning), trackerView (h.vm), configManager (h.cm)
@surface   tuning.stepToMidi, vm:activeTemper, cm:set
@harness   mk{seed.ccs}

# Intent
  Pins the projection contract of newViewContext directly, without
  going through vm. The context is built by hand from synthetic args so
  failures localise to newViewContext rather than to vm:rebuild's wiring.
  vm-integration tests live in vm_grid_spec.

# Helpers
  @fn logicalGrid()  @ 13-17
      -- Uniform logical grid for 240 ppq/QN, 4 rows/beat, length 3840 ppq.
  @fn mkCtx(overrides)  @ 19-31
  @fn mkCtxRpb(rpb, ppqPerQN)  @ 37-48
      -- Non-divisor rpb: ppqPerRow is fractional, so row · ppqPerRow lands
      -- between integers for most rows. Pins that rowToPPQ / ppqToRow are
      -- now both float — the old F4 asymmetry (rowToPPQ rounded at the
      -- realisation boundary) is gone; "on the grid" is owned by isOnGrid.
  @fn threeCallForm(ctx, ppq, chan)  @ 54-59
      -- The three-call form ctx:placeRow replaces: ppqToRow (the tail's start
      -- row), trackerView's ppqRowOf (snap when on-grid, else floor) and
      -- isOnGrid. Recomposed here so the cases compare definitions rather
      -- than hard-coded numbers.
  @fn eqThreeCallForm(ctx, ppq, label)  @ 61-67

# Cases
  @case 'identity swing: ppqToRow / rowToPPQ round-trip on grid-aligned rows'  [pure]  @ 73-80
  @case 'identity swing: ppqToRow and rowToPPQ are exact inverses, both returning float'  [pure]  @ 84-92
  @case 'snapRow snaps fractional ppq to the nearest row'  [pure]  @ 96-105
  @case 'ppq above length saturates at numRows; ppq below 0 saturates at 0'  [pure]  @ 109-116
  @case 'snapRow(rowToPPQ(r,c),c) == r under non-divisor rpb'  [pure]  @ 126-135
  @case 'on-grid p round-trips exactly under non-divisor rpb'  [pure]  @ 139-149
  @case 'ppqToRow ∘ rowToPPQ is the identity (float) under non-divisor rpb'  [pure]  @ 153-166
  @case 'isOnGrid: exact row ppqs are on-grid'  [pure]  @ 172-179
  @case 'isOnGrid: tolerates float drift up to (but not including) 0.5 ppq'  [pure]  @ 183-194
  @case 'isOnGrid: rebuild-inverted ppqs land on-grid under non-divisor rpb'  [pure]  @ 198-209
  @case 'placeRow agrees with the three-call form on grid, drift, off-grid and both clamps'  [pure]  @ 215-230
  @case 'placeRow: the three views are the row, its cell row and the on-grid verdict'  [pure]  @ 234-247
  @case 'placeRow agrees with the three-call form under non-divisor rpb'  [pure]  @ 251-262
  @case 'ppqPerRow exposes the rebuild frame logical ppq width'  [pure]  @ 268-271
  @case 'activeTemper is nil when no temperament is bound'  [pure]  @ 277-280
  @case 'activeTemper returns the bound temperament object'  [pure]  @ 284-288
  @case 'noteProjection returns nil when no temperament is bound'  [pure]  @ 292-295
  @case 'noteProjection under 12EDO: pitch 60 maps to C-4 with zero gap'  [pure]  @ 299-306
  @case 'noteProjection signed gap: positive detune yields positive gap (sharp)'  [pure]  @ 310-317
  @case 'noteProjection: sub-epsilon detune offset reads on-temper (gap clamped)'  [pure]  @ 321-332
  @case 'noteProjection halfGap is half the cents-distance to the nearest neighbour'  [pure]  @ 336-348
  @case 'rowBeatInfo at row 0 under 4/4 reports (bar, beat) = (true, true)'  [pure]  @ 354-359
  @case 'rowBeatInfo at beat boundary: only beat flag set'  [pure]  @ 363-369
  @case 'rowBeatInfo at bar boundary: both flags set'  [pure]  @ 373-378
  @case 'rowBeatInfo at non-boundary row: both flags clear'  [pure]  @ 382-387
  @case 'rowBeatInfo respects mid-take time-sig change'  [pure]  @ 391-406
  @case 'barBeatSub at row 0 returns (1, 1, 1, ts)'  [pure]  @ 410-415
  @case 'barBeatSub mid-bar: (bar, beat, sub) walks the row index'  [pure]  @ 419-424
  @case 'barBeatSub crosses a time-sig change and resumes counting'  [pure]  @ 428-445
  @case 'ghosts: linear pair populates interior rows with proportional vals'  [harness]  @ 461-481
  @case 'ghosts: entries carry fromEvt and toEvt references'  [harness]  @ 485-504
  @case 'ghosts: step shape produces no ghosts'  [harness]  @ 508-523
  @case 'ghosts: single event yields no ghosts'  [harness]  @ 527-541
  @case 'ghosts: non-linear shape routes through tm:interpolate'  [harness]  @ 545-562
  @case 'temper resolves via cfg.tempers, falls back to built-in presets, returns nil for unknown names'  [harness]  @ 566-587

